<section class="content"><div class="page-intro"><p>Keep the response network moving by reviewing incoming requests.</p></div><div class="panel table-panel"><table><thead><tr><th>Request</th><th>Recipient</th><th>Need</th><th>Priority</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach (array_reverse($requests) as $request): ?><tr><td><strong><?= h($request['id']) ?></strong><small><?= h($request['created']) ?></small></td><td><?= h($request['recipient']) ?></td><td><?= h($request['blood_group']) ?> · <?= h((string) $request['units']) ?> unit(s)<small><?= h($request['hospital']) ?></small></td><td><span class="urgency <?= strtolower($request['urgency']) ?>"><?= h($request['urgency']) ?></span></td><td><span class="badge <?= status_class($request['status']) ?>"><?= h($request['status']) ?></span></td><td><form method="post" class="inline-form"><input type="hidden" name="action" value="admin_request"><input type="hidden" name="request_id" value="<?= h($request['id']) ?>"><select name="status"><option <?= $request['status'] === 'Approved' ? 'selected' : '' ?>>Approved</option><option <?= $request['status'] === 'Pending' ? 'selected' : '' ?>>Pending</option><option <?= $request['status'] === 'Fulfilled' ? 'selected' : '' ?>>Fulfilled</option><option <?= $request['status'] === 'Rejected' ? 'selected' : '' ?>>Rejected</option></select><button class="icon-button" title="Update">✓</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>